# nearest-source labels for all structure pixels; ties retain 1
import numpy as np
A=np.array(grid)
coords={v:np.argwhere(A==v) for v in [2,9]}
changes=[]
nearest_out=[r[:] for r in grid]
for r,c in np.argwhere(A==1):
    ds={v:np.abs(coords[v]-[r,c]).sum(axis=1).min() for v in [2,9]}
    winner=min(ds,key=ds.get)
    if ds[2]!=ds[9]: nearest_out[r][c]=winner; changes.append((int(r),int(c),ds[2],ds[9],winner))
len(changes),changes[:40]
